    CONSTRAINT ck_video_completion_event__video_position CHECK (video_position IN ('pre_roll', 'mid_roll', 'post_roll')),
    CONSTRAINT ck_video_completion_event__viewable_percentage CHECK (viewable_percentage BETWEEN 0 AND 100)
) PARTITION BY RANGE (event_timestamp);

CREATE TABLE performance.viewability_measurement (
    viewability_measurement_id uuid NOT NULL DEFAULT uuidv7(),
    asset_id uuid,
    buy_id uuid,
    campaign_id uuid,
    flight_id uuid,
    impression_event_id uuid,
    line_item_id uuid,
    media_placement_id uuid,
    programmatic_deal_id uuid,
    publisher_id uuid,
    sla_id uuid,
    spec_id uuid,
    supplier_id uuid,
    ad_format text,
    audible_on_complete_flag boolean NOT NULL DEFAULT false,
    brand_safety_flag boolean NOT NULL DEFAULT false,
    data_quality_score numeric(5,2),
    device_type text,
    environment text,
    guaranteed_viewability_threshold numeric(5,2),
    in_view_percentage numeric(5,2),
    invalid_traffic_flag boolean NOT NULL DEFAULT false,
    measurability_rate numeric(5,2),
    measurable_impression_count bigint,
    measurement_date date NOT NULL,
    measurement_method text,
    measurement_status text,
    measurement_timestamp timestamptz NOT NULL,
    mrc_compliant_flag boolean NOT NULL DEFAULT false,
    player_size_height integer,
    player_size_width integer,
    source_system text,
    time_in_view_seconds numeric(10,2),
    total_impression_count bigint,
    unmeasurable_reason text,
    video_quartile_reached text,
    viewability_guaranteed_io_flag boolean NOT NULL DEFAULT false,
    viewability_rate numeric(5,2),
    viewability_standard text,
    viewable_impression_count bigint,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by text NOT NULL DEFAULT audit.current_actor(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by text NOT NULL DEFAULT audit.current_actor(),
    CONSTRAINT pk_viewability_measurement PRIMARY KEY (viewability_measurement_id, measurement_timestamp),
    CONSTRAINT ck_viewability_measurement__ad_format CHECK (ad_format IN ('display', 'video', 'native', 'rich_media', 'interstitial', 'expandable')),
    CONSTRAINT ck_viewability_measurement__device_type CHECK (device_type IN ('desktop', 'mobile', 'tablet', 'CTV', 'OTT', 'DOOH')),
    CONSTRAINT ck_viewability_measurement__environment CHECK (environment IN ('web', 'in_app', 'CTV', 'DOOH')),
    CONSTRAINT ck_viewability_measurement__in_view_percentage CHECK (in_view_percentage BETWEEN 0 AND 100),
    CONSTRAINT ck_viewability_measurement__measurability_rate CHECK (measurability_rate >= 0),
    CONSTRAINT ck_viewability_measurement__measurable_impression_count CHECK (measurable_impression_count >= 0),
    CONSTRAINT ck_viewability_measurement__measurement_method CHECK (measurement_method IN ('geometric', 'browser_optimization', 'reach_extension')),
    CONSTRAINT ck_viewability_measurement__measurement_status CHECK (measurement_status IN ('measured', 'unmeasurable', 'pending', 'error')),
    CONSTRAINT ck_viewability_measurement__player_size_height CHECK (player_size_height >= 0),
    CONSTRAINT ck_viewability_measurement__player_size_width CHECK (player_size_width >= 0),
    CONSTRAINT ck_viewability_measurement__time_in_view_seconds CHECK (time_in_view_seconds >= 0),
    CONSTRAINT ck_viewability_measurement__total_impression_count CHECK (total_impression_count >= 0),
    CONSTRAINT ck_viewability_measurement__video_quartile_reached CHECK (video_quartile_reached IN ('0%', '25%', '50%', '75%', '100%', 'not_applicable')),
    CONSTRAINT ck_viewability_measurement__viewability_rate CHECK (viewability_rate >= 0),
    CONSTRAINT ck_viewability_measurement__viewability_standard CHECK (viewability_standard IN ('MRC_display', 'MRC_video', 'GroupM', 'custom')),
    CONSTRAINT ck_viewability_measurement__viewable_impression_count CHECK (viewable_impression_count >= 0)
) PARTITION BY RANGE (measurement_timestamp);
